import { splitProps, type JSX, type ParentProps } from 'solid-js';
import { bubbleStyleKeys, getBubbleStyleKeys } from '../lib/core';
import type { BubbleBaseProps, BubbleReactionsBaseProps } from '../lib/core';
import styles from './bubble.module.scss';

export interface BubbleGroupProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export function BubbleGroup(props: ParentProps<BubbleGroupProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<div {...rest} data-slot="bubble-group" class={`${styles[bubbleStyleKeys.group]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}
export interface BubbleProps extends JSX.HTMLAttributes<HTMLDivElement>, BubbleBaseProps {}
export function Bubble(props: ParentProps<BubbleProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'variant', 'align']);
	const keys = () => getBubbleStyleKeys(local.variant ?? 'default');
	return (
		<div
			{...rest}
			data-slot="bubble"
			data-variant={local.variant ?? 'default'}
			data-align={local.align ?? 'start'}
			class={`${styles[keys().base]} ${styles[keys().variant]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}
export interface BubbleContentProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export function BubbleContent(props: ParentProps<BubbleContentProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<div {...rest} data-slot="bubble-content" class={`${styles[bubbleStyleKeys.content]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}
export interface BubbleReactionsProps extends JSX.HTMLAttributes<HTMLDivElement>, BubbleReactionsBaseProps {}
export function BubbleReactions(props: ParentProps<BubbleReactionsProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'side', 'align']);
	return (
		<div
			{...rest}
			data-slot="bubble-reactions"
			data-side={local.side ?? 'bottom'}
			data-align={local.align ?? 'end'}
			class={`${styles[bubbleStyleKeys.reactions]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}
export default Bubble;

@use '../../../styles/variables/colors' as *;

// 气泡组
.group {
	display: flex;
	width: 100%;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-2;
}

// 气泡根容器
.bubble {
	position: relative;
	display: flex;
	width: fit-content;
	max-width: 80%;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-1;

	&[data-align='end'] {
		align-self: flex-end;

		.content {
			align-self: flex-end;
		}
	}

	&[data-variant='ghost'] {
		max-width: 100%;
	}

	&:has(.reactions[data-side='top']) {
		margin-top: $spacing-3;
	}

	&:has(.reactions[data-side='bottom']) {
		margin-bottom: $spacing-3;
	}

	// 变体
	&.variantDefault .content {
		background-color: var(--tile-bubble-background, $primary);
		color: var(--tile-bubble-color, $primary-foreground);
	}

	&.variantSecondary .content {
		background-color: var(--tile-bubble-secondary-background, $secondary);
		color: $secondary-foreground;
	}

	&.variantMuted .content {
		background-color: var(--tile-bubble-muted-background, $muted);
		color: $foreground;
	}

	&.variantTinted .content {
		background-color: var(--tile-bubble-tinted-background, color-mix(in srgb, $primary 15%, $background));
		color: $foreground;
	}

	&.variantOutline .content {
		border-color: var(--tile-bubble-border, $border);
		background-color: var(--tile-bubble-outline-background, $background);
		color: $foreground;
	}

	&.variantGhost .content {
		border: none;
		border-radius: 0;
		background-color: transparent;
		padding: 0;
	}

	&.variantDestructive .content {
		background-color: var(--tile-bubble-error-background, color-mix(in srgb, $destructive 10%, transparent));
		color: var(--tile-bubble-error-color, $destructive);
	}

	// 按钮/链接形态的内容悬停效果
	&.variantDefault .content:is(button, a):hover {
		background-color: var(--tile-bubble-hover-background, color-mix(in srgb, $primary 80%, transparent));
	}

	&.variantSecondary .content:is(button, a):hover,
	&.variantMuted .content:is(button, a):hover,
	&.variantGhost .content:is(button, a):hover,
	&.variantOutline .content:is(button, a):hover {
		background-color: $muted;
		color: $foreground;
	}

	&.variantDestructive .content:is(button, a):hover {
		background-color: var(--tile-bubble-error-hover-background, color-mix(in srgb, $destructive 20%, transparent));
	}
}

// 气泡内容
.content {
	display: block;
	width: fit-content;
	max-width: 100%;
	min-width: 0;
	overflow: hidden;
	border: 1px solid transparent;
	border-radius: var(--tile-bubble-radius, $radius);
	padding: var(--tile-bubble-padding, $spacing-2 $spacing-3);
	font-size: $text-sm;
	line-height: $leading-relaxed;
	overflow-wrap: anywhere;
	word-break: break-word;

	&:is(button, a) {
		text-align: left;
		transition:
			background-color $transition-fast,
			border-color $transition-fast,
			box-shadow $transition-fast;
		outline: none;
	}

	&:is(button, a):focus-visible {
		border-color: $ring;
		box-shadow: var(--tile-bubble-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}
}

// 气泡反应区 (绝对定位于气泡边缘)
.reactions {
	position: absolute;
	z-index: 10;
	display: flex;
	width: fit-content;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	gap: $spacing-1;
	border-radius: $radius-full;
	background-color: var(--tile-bubble-reactions-background, $muted);
	padding: 0.125rem $spacing-1_5;
	font-size: $text-sm;
	box-shadow: 0 0 0 3px $card;

	&[data-side='top'] {
		top: 0;
		transform: translateY(-75%);
	}

	&[data-side='bottom'] {
		bottom: 0;
		transform: translateY(75%);
	}

	&[data-align='start'] {
		left: $spacing-3;
	}

	&[data-align='end'] {
		right: $spacing-3;
	}
}
